/* Card set: Reptiles & Amphibians (generated from the approved roster-final.csv by the Reptiles build, schema per tools/csv-to-set.js).
   (reptiles.js exceeds the comfortable push size, so the remaining cards live in
   reptiles-additions.js, which must stay directly after 'reptiles.js' in sets/manifest.js.) */
CardSets.register({"id":"reptiles","name":"Reptiles & Amphibians","code":"REPT","description":"420 cards of scales, shells and smooth skin - snakes and lizards, frogs and toads, turtles, crocodilians, salamanders and more.","theme":{"primary":"#256d46","secondary":"#b7791f","artBackground":"#eef2e2","artFit":"cover"},"pack":{"name":"Reptiles & Amphibians Pack","emblem":"🐍","skin":"reptiles"},"cards":[{"name":"King Cobra","rarity":"chase","id":"king-cobra","subtitle":"Snake","details":"The world's longest venomous snake, reaching over 5 metres, this Asian forest snake raises its forebody high and spreads a narrow hood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ophiophagus%20hannah%20381373252.jpg?width=1024"},{"name":"Komodo Dragon","rarity":"chase","id":"komodo-dragon","subtitle":"Lizard","details":"The largest living lizard, from a few Indonesian islands. Adults can top 3 metres and hunt deer and buffalo with a powerful bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Komodo%20dragon%20%28Varanus%20komodoensis%29.jpg?width=1024"},{"name":"Green Anaconda","rarity":"chase","id":"green-anaconda","subtitle":"Snake","details":"A giant of Amazon swamps and rivers, this heavy-bodied boa can exceed 5 metres and spends much of its life half-submerged in slow water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eunectes%20murinus%20%281%29.jpg?width=1024"},{"name":"Golden Poison Frog","rarity":"chase","id":"golden-poison-frog","subtitle":"Frog","details":"A brilliant gold frog from Colombia's Pacific rainforests, about 5 cm long. Its bright skin warns predators to leave it alone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20Poison%20dart%20frog%20Phyllobates%20terribilis.jpg?width=1024"},{"name":"Panther Chameleon","rarity":"chase","id":"panther-chameleon","subtitle":"Lizard","details":"A vivid chameleon of northern and eastern Madagascar. Males shift from green to turquoise and red with mood, health and display.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Furcifer%20pardalis%20188585705.jpg?width=1024"},{"name":"Axolotl","rarity":"chase","id":"axolotl","subtitle":"Salamander","details":"Native only to lake channels near Mexico City, this neotenic salamander keeps its feathery gills for life and can regrow lost limbs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/6%20maja%2006%20r.%20ZOO%20204.jpg?width=1024"},{"name":"Gila Monster","rarity":"chase","id":"gila-monster","subtitle":"Lizard","details":"A stout, bead-scaled lizard of Sonoran Desert country in the southwestern US and Mexico. It stores fat in its thick, banded tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gila%20monster%20%28Heloderma%20suspectum%29.jpg?width=1024"},{"name":"American Alligator","rarity":"chase","id":"american-alligator","subtitle":"Alligator","details":"A broad-snouted alligator of southeastern US swamps and marshes, reaching about 4 metres, with dark armoured skin and a powerful tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alligator%20mississippiensis%20113744549.jpg?width=1024"},{"name":"Gaboon Viper","rarity":"chase","id":"gaboon-viper","subtitle":"Snake","details":"Africa's heaviest viper hides in rainforest leaf litter, its geometric brown pattern vanishing among dead leaves despite its great size.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bitis%20gabonica.jpg?width=1024"},{"name":"Aldabra Giant Tortoise","rarity":"chase","id":"aldabra-giant-tortoise","subtitle":"Tortoise","details":"Giant tortoise of Aldabra Atoll in the Seychelles, reaching over a metre long, with a tall domed shell and a very long neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aldabra%20giant%20tortoise%20%28Aldabrachelys%20gigantea%29%20-%20Alibel%20Tortoise%20Park%20-%20Mahe%20-%20Seychelles%20-%2001.jpg?width=1024"},{"name":"Black Mamba","rarity":"legendary","id":"black-mamba","subtitle":"Snake","details":"A long, fast snake of eastern and southern African savanna, named for the dark interior of its mouth rather than its grey-brown scales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dendroaspis%20polylepis.jpg?width=1024"},{"name":"Inland Taipan","rarity":"legendary","id":"inland-taipan","subtitle":"Snake","details":"Found in the dry floodplains of inland Australia, this shy, slender elapid changes shade with the seasons, darker in winter, paler in summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fierce%20Snake-Oxyuranus%20microlepidotus.jpg?width=1024"},{"name":"Reticulated Python","rarity":"legendary","id":"reticulated-python","subtitle":"Snake","details":"Southeast Asia's longest snake, patterned in a net-like web of gold and brown, with wild individuals recorded at well over 6 metres long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malayopython%20reticulatus%2C%20Reticulated%20python%20-%20Kaeng%20Krachan%20District%2C%20Phetchaburi%20Province%20%2847924282891%29.jpg?width=1024"},{"name":"Eastern Diamondback Rattlesnake","rarity":"legendary","id":"eastern-diamondback-rattlesnake","subtitle":"Snake","details":"The heaviest venomous snake in North America, this southeastern rattler carries bold diamond markings edged in pale yellow along its back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crotalus%20adamanteus%20%285%29.jpg?width=1024"},{"name":"South American Bushmaster","rarity":"legendary","id":"south-american-bushmaster","subtitle":"Snake","details":"The longest viper in the Americas, this rare rainforest pit viper of Central and South America can grow beyond 3 metres in quiet forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lachesis%20muta%20muta.jpg?width=1024"},{"name":"Tiger Snake","rarity":"legendary","id":"tiger-snake","subtitle":"Snake","details":"A stout, highly variable snake of southern Australian wetlands and coasts, often banded like its namesake and an able swimmer in marshes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Notechis%20scutatus%20260523890.jpg?width=1024"},{"name":"Forest Cobra","rarity":"legendary","id":"forest-cobra","subtitle":"Snake","details":"One of Africa's largest cobras, this agile forest and savanna snake can climb well and raises a long, narrow hood when it feels threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Naja%20melanoleuca%20187777696.jpg?width=1024"},{"name":"Coastal Taipan","rarity":"legendary","id":"coastal-taipan","subtitle":"Snake","details":"A large, fast snake of northern and eastern Australian coastlines, pale to reddish brown, hunting rats and bandicoots in cane fields and scrub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CSIRO%20ScienceImage%203625%20Taipan.jpg?width=1024"},{"name":"Green Iguana","rarity":"legendary","id":"green-iguana","subtitle":"Lizard","details":"A large, leaf-eating iguana of Central and South American forests. Strong swimmers, they often rest on branches overhanging water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close-up%20photograph%20of%20an%20Iguana%20iguana.jpg?width=1024"},{"name":"Veiled Chameleon","rarity":"legendary","id":"veiled-chameleon","subtitle":"Lizard","details":"A tall-crested chameleon native to the Arabian Peninsula. Its long, sticky tongue can shoot out farther than its own body length.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaeleo%20calyptratus%2001.jpg?width=1024"},{"name":"Savannah Monitor","rarity":"legendary","id":"savannah-monitor","subtitle":"Lizard","details":"A stocky monitor of African grasslands and savannas. It digs well and feeds on snails, eggs, insects and other small animals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanus%20exanthematicus%2001.jpg?width=1024"},{"name":"Jackson's Chameleon","rarity":"legendary","id":"jacksons-chameleon","subtitle":"Lizard","details":"An East African chameleon whose males carry three horns on the snout. It gives birth to live young rather than laying eggs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trioceros%20jacksonii%20124092193.jpg?width=1024"},{"name":"Eastern Blue-tongued Skink","rarity":"legendary","id":"eastern-blue-tongued-skink","subtitle":"Lizard","details":"An Australian skink named for its vivid blue tongue, which it flashes at predators. It is slow, sturdy and largely ground-dwelling.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20blue-tongued%20lizard%20-%20Tiliqua%20scincoides%20scincoides%20-%204.jpg?width=1024"},{"name":"Argentine Black and White Tegu","rarity":"legendary","id":"argentine-black-and-white-tegu","subtitle":"Lizard","details":"A large South American tegu with bold black-and-white patterning. It is a strong digger and an opportunistic, wide-ranging feeder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salvator%20merianae%20-%20Gab%20Buffo%20-%20429687602.jpeg?width=1024"},{"name":"Mexican Beaded Lizard","rarity":"legendary","id":"mexican-beaded-lizard","subtitle":"Lizard","details":"A heavy, bead-scaled lizard of dry forests in western Mexico and Guatemala. It spends much of its life in burrows and rocky retreats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heloderma%20horridum.jpg?width=1024"},{"name":"Goliath Frog","rarity":"legendary","id":"goliath-frog","subtitle":"Frog","details":"The world's largest frog, from Cameroon and Equatorial Guinea. It can top 30 cm and 3 kg, and builds rocky nests in fast rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conraua%20goliath%20photo%20from%20iNaturalist%20539752953.jpg?width=1024"},{"name":"Red-eyed Tree Frog","rarity":"legendary","id":"red-eyed-tree-frog","subtitle":"Frog","details":"A slender green tree frog of Central American rainforests, famous for huge red eyes and bright blue and orange flanks and legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red-eyed%20Tree%20Frog%20%28Agalychnis%20callidryas%29%203.jpg?width=1024"},{"name":"Strawberry Poison Dart Frog","rarity":"legendary","id":"strawberry-poison-dart-frog","subtitle":"Frog","details":"A tiny red dart frog of Central America, often with blue legs. Parents carry tadpoles up to water held in bromeliad leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oophaga%20pumilio%20263283848.jpg?width=1024"},{"name":"Blue Poison Dart Frog","rarity":"legendary","id":"blue-poison-dart-frog","subtitle":"Frog","details":"A vivid sky-blue dart frog from southern Suriname, marked with black spots. Each frog's spot pattern is unique to that frog.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dendrobates%20azureus%20qtl1.jpg?width=1024"},{"name":"Panamanian Golden Frog","rarity":"legendary","id":"panamanian-golden-frog","subtitle":"Frog","details":"A bright gold frog from Panama's mountain streams. It waves a forelimb in circles to signal to rivals beside loud water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atelopus%20zeteki01b.jpg?width=1024"},{"name":"Australian Green Tree Frog","rarity":"legendary","id":"australian-green-tree-frog","subtitle":"Frog","details":"A large, calm green tree frog of Australia and New Guinea, reaching 11 cm. It often shelters in cool, damp places near homes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ranoidea%20caerulea%20-%20Wilhelma%2001.jpg?width=1024"},{"name":"Malagasy Rainbow Frog","rarity":"legendary","id":"malagasy-rainbow-frog","subtitle":"Frog","details":"A striking red, green and black burrowing frog from Madagascar. It climbs rock walls and inflates its body when threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scaphiophryne%20gottlebei01.jpg?width=1024"},{"name":"Galapagos Giant Tortoise","rarity":"legendary","id":"galapagos-giant-tortoise","subtitle":"Tortoise","details":"Giant tortoise of the Galapagos Islands, with saddleback or domed shells varying by island, reaching well over a metre in length.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gal%C3%A1pagos%20giant%20tortoise%2C%20moving%20%28Chelonoidis%20niger%20hoodensis%29.jpg?width=1024"},{"name":"Alligator Snapping Turtle","rarity":"legendary","id":"alligator-snapping-turtle","subtitle":"Turtle","details":"Huge freshwater turtle of Gulf Coast rivers in the United States, with a spiked shell, massive hooked beak and worm-like tongue lure.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skorpucha%20s%C4%99pia%20%E2%80%93%20Alligator%20snapping%20turtle%20%E2%80%93%20Macrochelys%20temminckii.jpg?width=1024"},{"name":"Radiated Tortoise","rarity":"legendary","id":"radiated-tortoise","subtitle":"Tortoise","details":"Madagascar tortoise named for the bright yellow lines radiating across each dark scute of its high, smoothly domed shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Radiated%20tortoise%20%28Astrochelys%20radiata%29%20Tsimanampetsotsa.jpg?width=1024"},{"name":"African Spurred Tortoise","rarity":"legendary","id":"african-spurred-tortoise","subtitle":"Tortoise","details":"Large grazing tortoise of the southern Sahara and Sahel, digging deep burrows, with a broad tan shell and strong spurred thighs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African%20spurred%20tortoise%20%28Centrochelys%20sulcata%29%2C%20Gembira%20Loka%20Zoo%2C%202015-03-15.jpg?width=1024"},{"name":"Nile Crocodile","rarity":"legendary","id":"nile-crocodile","subtitle":"Crocodile","details":"A large crocodile of African rivers and lakes, growing past 5 metres, with a broad snout, conical teeth and olive-grey armoured skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nile%20crocodile%20in%20the%20Zambezi.jpg?width=1024"},{"name":"Gharial","rarity":"legendary","id":"gharial","subtitle":"Gharial","details":"A fish-eating crocodilian of northern Indian rivers, unmistakable for its very long, thin snout lined with over a hundred sharp teeth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gharial%20%28Gavialis%20gangeticus%29%20male.jpg?width=1024"},{"name":"Japanese Giant Salamander","rarity":"legendary","id":"japanese-giant-salamander","subtitle":"Salamander","details":"One of the world's largest amphibians, this nocturnal giant hunts fish and crabs in cold, clear mountain streams across Japan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019%20Andrias%20japonicus%20-%20Ueno%20Zoo.jpg?width=1024"},{"name":"Chinese Giant Salamander","rarity":"legendary","id":"chinese-giant-salamander","subtitle":"Salamander","details":"A huge, fully aquatic salamander of rocky Chinese streams, it can grow well over a metre long and breathes largely through its skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2009%20Andrias%20davidianus.JPG?width=1024"},{"name":"Eastern Green Mamba","rarity":"epic","id":"eastern-green-mamba","subtitle":"Snake","details":"A bright green, slender snake of East African coastal forests, moving gracefully through trees and shrubs in search of birds and small mammals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20green%20mamba%20%28Dendroaspis%20angusticeps%29.jpg?width=1024"},{"name":"Boomslang","rarity":"epic","id":"boomslang","subtitle":"Snake","details":"A long, thin tree snake of sub-Saharan Africa with huge eyes and strong binocular vision; males are green, females usually browner in colour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boomslang%20%28Dispholidus%20typus%29%20at%20Nairobi%20Snake%20Park%201.jpg?width=1024"},{"name":"Burmese Python","rarity":"epic","id":"burmese-python","subtitle":"Snake","details":"One of the world's largest snakes, this Southeast Asian python frequents wetlands and forest edges and is a powerful, patient constrictor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Python%20bivittatus%201701.jpg?width=1024"},{"name":"Boa Constrictor","rarity":"epic","id":"boa-constrictor","subtitle":"Snake","details":"A heavy-bodied snake of Central and South American forests and scrub, marked with dark saddles and a distinctive arrow-shaped mark on the head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boa%20constrictor%2C%20Va%C5%88kovka%2C%20Brno%20%282%29.jpg?width=1024"},{"name":"Emerald Tree Boa","rarity":"epic","id":"emerald-tree-boa","subtitle":"Snake","details":"A vivid green Amazon basin boa that rests coiled over branches by day, its white zigzag markings breaking up its outline among the leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Corallus%20caninus.JPG?width=1024"},{"name":"Rainbow Boa","rarity":"epic","id":"rainbow-boa","subtitle":"Snake","details":"Named for the iridescent sheen on its orange-brown scales, this Central and South American boa hunts at night near forest streams and clearings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Epicrates%20cenchria%20158446770.jpg?width=1024"},{"name":"Russell's Viper","rarity":"epic","id":"russells-viper","subtitle":"Snake","details":"A thick-bodied South and Southeast Asian viper with neat rows of dark oval spots, common in farmland and grassland across its broad range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Daboia%20russelii%20A%20Chawla01.jpg?width=1024"},{"name":"Saw-scaled Viper","rarity":"epic","id":"saw-scaled-viper","subtitle":"Snake","details":"A small, rough-scaled viper of dry regions from Africa to India; it rubs its scales together to make a sizzling warning sound like sawing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echis%20carinatus%20carinatus%20143225905.jpg?width=1024"},{"name":"Puff Adder","rarity":"epic","id":"puff-adder","subtitle":"Snake","details":"A heavy, slow-moving viper found across much of Africa, relying on camouflage in dry grassland and taking its name from its loud hissing display.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bitis%20arietans.jpg?width=1024"},{"name":"Cottonmouth","rarity":"epic","id":"cottonmouth","subtitle":"Snake","details":"A thick-bodied pit viper of southeastern US wetlands, named for the white interior of its mouth, which it shows in a gaping defensive display.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Florida%20Water%20Moccasin%20056.jpg?width=1024"},{"name":"Eastern Coral Snake","rarity":"epic","id":"eastern-coral-snake","subtitle":"Snake","details":"A slender, glossy snake of the southeastern United States with bright red, yellow and black bands and a shy, burrowing life in sandy soils.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/EASTERN%20CORAL%20SNAKE%201.jpg?width=1024"},{"name":"Fer-de-Lance","rarity":"epic","id":"fer-de-lance","subtitle":"Snake","details":"A large, fast pit viper of Central American lowlands, its lance-shaped head and patterned back blending into forest floor and plantation litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bothrops%20asper%20%28Panama%29%20head.jpg?width=1024"},{"name":"Nile Monitor","rarity":"epic","id":"nile-monitor","subtitle":"Lizard","details":"Africa's largest monitor, at home along rivers and lakes. A powerful swimmer, it feeds on fish, eggs, crabs and carrion alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nile%20monitor%20%28Varanus%20niloticus%29%202.jpg?width=1024"},{"name":"Asian Water Monitor","rarity":"epic","id":"asian-water-monitor","subtitle":"Lizard","details":"One of the world's heaviest lizards, widespread across South and Southeast Asia. It swims strongly using its laterally flat tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Closeup%20shot%20of%20Water%20monitor%20lizard%2C%20Varanus%20salvator%20from%20Diamond%20Harbour%2C%20WB%2C%20In%2003.jpg?width=1024"},{"name":"Frilled Lizard","rarity":"epic","id":"frilled-lizard","subtitle":"Lizard","details":"An Australian lizard famous for the great frill around its neck, which flares wide to startle predators before it flees uphill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chlamydosaurus%20kingii%20166371854.jpg?width=1024"},{"name":"Thorny Devil","rarity":"epic","id":"thorny-devil","subtitle":"Lizard","details":"A spiny Australian desert lizard covered in sharp cones. Grooves between its scales channel dew and rainwater toward its mouth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moloch%20horridus%2C%20Thorny%20Devil%2C%20Alice%20Springs.jpg?width=1024"},{"name":"Tokay Gecko","rarity":"epic","id":"tokay-gecko","subtitle":"Lizard","details":"A large, boldly spotted Asian gecko named for its loud two-note call. Adhesive toe pads let it climb smooth walls and ceilings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gekko%20gecko%20221285.jpg?width=1024"},{"name":"Philippine Sailfin Lizard","rarity":"epic","id":"philippine-sailfin-lizard","subtitle":"Lizard","details":"A large Philippine lizard with a sail-like crest on its tail base. Semi-aquatic, it can run short distances across the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hydrosaurus%20pustulatus%203.jpg?width=1024"},{"name":"Green Basilisk","rarity":"epic","id":"green-basilisk","subtitle":"Lizard","details":"A Central American lizard famed for sprinting bipedally across water on fringed hind toes, sinking only after several metres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Basiliscus%20plumifrons%2010299135.jpg?width=1024"},{"name":"Rhinoceros Iguana","rarity":"epic","id":"rhinoceros-iguana","subtitle":"Lizard","details":"A heavy Caribbean iguana of Hispaniola, named for the horn-like scale on a male's snout. It basks on limestone and dry scrub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cyclura%20cornuta.004%20-%20Zoo%20Aquarium%20de%20Madrid.JPG?width=1024"},{"name":"Fiji Banded Iguana","rarity":"epic","id":"fiji-banded-iguana","subtitle":"Lizard","details":"A bright green iguana of Fiji and Tonga, the males banded in pale blue-green. It lives in coastal and lowland forest canopies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20180613%20Brachylophus%20fasciatus%2001.jpg?width=1024"},{"name":"Chinese Water Dragon","rarity":"epic","id":"chinese-water-dragon","subtitle":"Lizard","details":"A green, crested lizard of southern China and Southeast Asia. At home near streams, it dives and can stay submerged for minutes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinese%20Water%20Dragon%20%28Physignathus%20cocincinus%29%20-%20Khao%20Yai%20National%20Park%20-%201.jpg?width=1024"},{"name":"Egyptian Mastigure","rarity":"epic","id":"egyptian-mastigure","subtitle":"Lizard","details":"A bulky spiny-tailed lizard of North African and Middle Eastern deserts. It shelters in deep burrows and basks at their mouths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uromastyx%20aegyptia%202.jpg?width=1024"},{"name":"Tomato Frog","rarity":"epic","id":"tomato-frog","subtitle":"Frog","details":"A plump, tomato-red frog from Madagascar that grows to about 10 cm. When threatened it puffs up and oozes a sticky skin glue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dyscophus%20antongilii%20186311549.jpg?width=1024"},{"name":"Argentine Horned Frog","rarity":"epic","id":"argentine-horned-frog","subtitle":"Frog","details":"A wide-mouthed, horn-browed frog of South American grasslands. It buries itself in soil and ambushes prey that wanders past.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argentine%20Horned%20Frog%20%28Ceratophrys%20ornata%291.JPG?width=1024"},{"name":"Cane Toad","rarity":"epic","id":"cane-toad","subtitle":"Toad","details":"A very large, warty toad native to Central and South America, reaching over 20 cm. It hunts at night around lights and ponds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cane%20toad%20%28Rhinella%20marina%29%20%289575448703%29.jpg?width=1024"},{"name":"American Bullfrog","rarity":"epic","id":"american-bullfrog","subtitle":"Frog","details":"North America's largest frog, named for its deep, bellowing call. Big males defend pond edges through the summer breeding season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/North-American-bullfrog1.jpg?width=1024"},{"name":"Northern Glass Frog","rarity":"epic","id":"northern-glass-frog","subtitle":"Frog","details":"A tiny translucent tree frog of Central and South America. From below, its organs and bones show through its clear belly skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hyalinobatrachium%20fleischmanni.jpg?width=1024"},{"name":"Wallace's Flying Frog","rarity":"epic","id":"wallaces-flying-frog","subtitle":"Frog","details":"A large green tree frog of Borneo and Malaysia that glides between trees on huge, fully webbed black-edged hands and feet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhacophorus%20nigropalmatus.jpg?width=1024"},{"name":"African Bullfrog","rarity":"epic","id":"african-bullfrog","subtitle":"Frog","details":"A massive, heavy-bodied frog of African savannas. Males guard tadpoles in drying pools and dig channels to deeper water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pyxicephalus%20adspersus%2C%20Boston%20Aquarium.jpg?width=1024"},{"name":"Surinam Toad","rarity":"epic","id":"surinam-toad","subtitle":"Toad","details":"A completely aquatic, flat-bodied toad of South America. Eggs develop in pockets on the mother's back until froglets emerge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pipa%20pipa01.jpg?width=1024"},{"name":"Indian Purple Frog","rarity":"epic","id":"indian-purple-frog","subtitle":"Frog","details":"A bloated, purple burrowing frog from India's Western Ghats, with a pointed snout. It surfaces briefly each year to breed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nasikabatrachus%20sahyadrensis.jpg?width=1024"},{"name":"Hairy Frog","rarity":"epic","id":"hairy-frog","subtitle":"Frog","details":"A Central African frog whose breeding males grow hair-like skin flaps on their sides and thighs that help absorb oxygen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trichobatrachus%20robustus.JPG?width=1024"},{"name":"Matamata","rarity":"epic","id":"matamata","subtitle":"Turtle","details":"South American river turtle with a rough, algae-coated shell, broad flat head and snorkel-like snout used to breathe at the surface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chelidae%20Chelus%20fimbriata%202.jpg?width=1024"},{"name":"Common Snapping Turtle","rarity":"epic","id":"common-snapping-turtle","subtitle":"Turtle","details":"Heavy freshwater turtle of North American ponds and marshes, with a rugged shell, powerful jaws and a long, saw-edged tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Snapping%20Turtle%20%28Chelydra%20serpentina%29%20-%20June%2C%202025%2C%20Illinois.jpg?width=1024"},{"name":"Pig-nosed Turtle","rarity":"epic","id":"pig-nosed-turtle","subtitle":"Turtle","details":"River turtle of northern Australia and New Guinea, with flippers like a sea turtle, a leathery shell and a fleshy pig-like snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pig-Nosed%20Turtle%20Carettochelys%20insculpta%20Diving%202260px.jpg?width=1024"},{"name":"Indian Star Tortoise","rarity":"epic","id":"indian-star-tortoise","subtitle":"Tortoise","details":"Tortoise of India, Pakistan and Sri Lanka, each shell scute marked with a striking black and yellow star pattern of radiating lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indian%20star%20tortoise%28Geochelone%20elegans%29%20IGZoo%20park%20Visakhapatnam.JPG?width=1024"},{"name":"Leopard Tortoise","rarity":"epic","id":"leopard-tortoise","subtitle":"Tortoise","details":"Spotted, high-domed tortoise of eastern and southern African savannas, grazing grasses across dry grassland and thorn scrub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Old%20leopard%20tortoise%20%28Stigmochelys%20pardalis%29%20at%20Nairobi%20Snake%20Park.jpg?width=1024"},{"name":"Big-headed Turtle","rarity":"epic","id":"big-headed-turtle","subtitle":"Turtle","details":"Stream turtle of southern China and Southeast Asia whose huge head cannot withdraw into its shell, armed with a strong hooked beak.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Platysternon%20megacephalum%20208194728.jpg?width=1024"},{"name":"Spider Tortoise","rarity":"epic","id":"spider-tortoise","subtitle":"Tortoise","details":"Tiny Madagascar tortoise with a hinged front shell section and fine yellow web-like lines over its dark, domed carapace.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spider%20tortoise%20%28Pyxis%20arachnoides%20archnoides%29%20Tsimanampetsotsa.jpg?width=1024"},{"name":"Black Caiman","rarity":"epic","id":"black-caiman","subtitle":"Caiman","details":"The largest caiman, from Amazon basin rivers and flooded forest, reaching about 5 metres, with dark skin and a broad, heavy snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20Caiman%20%28Melanosuchus%20niger%29%20%28Captive%20specimen%29%20%2826670892808%29.jpg?width=1024"},{"name":"Cuban Crocodile","rarity":"epic","id":"cuban-crocodile","subtitle":"Crocodile","details":"A compact, strongly patterned crocodile found only in Cuban swamps, growing to about 3.5 metres, with long legs and a blunt snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crocodylidae%20Crocodylus%20rhombifer%201.jpg?width=1024"},{"name":"Chinese Alligator","rarity":"epic","id":"chinese-alligator","subtitle":"Alligator","details":"A small alligator of the lower Yangtze River in China, reaching about 2 metres, with a short, upturned snout and heavily armoured body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alligator%20sinensis.jpg?width=1024"},{"name":"Hellbender","rarity":"epic","id":"hellbender","subtitle":"Salamander","details":"North America's largest salamander, this flat, wrinkled river dweller hides under rocks by day and absorbs oxygen through its skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cryptobranchus%20alleganiensis%20159117770.jpg?width=1024"},{"name":"Fire Salamander","rarity":"epic","id":"fire-salamander","subtitle":"Salamander","details":"A bold black-and-yellow salamander of European woodlands, it emerges after rain to hunt slugs, worms and insects on the forest floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20fire%20salamander%20%28Salamandra%20salamandra%29.jpg?width=1024"},{"name":"Olm","rarity":"epic","id":"olm","subtitle":"Salamander","details":"A blind, pale cave salamander of Balkan underground rivers, it keeps its larval gills for life and can live for many decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Proteus%20anguinus%20anguinus%2048298877.jpg?width=1024"},{"name":"Western Diamondback Rattlesnake","rarity":"rare","id":"western-diamondback-rattlesnake","subtitle":"Snake","details":"An iconic rattler of the American Southwest and Mexico, grey-brown with diamond blotches and bold black-and-white bands before the rattle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crotalus%20atrox%20USFWS.jpg?width=1024"},{"name":"Timber Rattlesnake","rarity":"rare","id":"timber-rattlesnake","subtitle":"Snake","details":"A heavy-bodied rattlesnake of eastern North American forests and rocky hillsides, varying from yellow with dark bands to almost entirely black.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/C%20horridus.JPG?width=1024"},{"name":"Mojave Rattlesnake","rarity":"rare","id":"mojave-rattlesnake","subtitle":"Snake","details":"A desert pit viper of the Mojave and Mexican plateau, pale greenish or brown with diamond markings and a rattle banded in black and white.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crotalus%20scutulatus%20-%20Flickr%20-%20aspidoscelis.jpg?width=1024"},{"name":"Sidewinder","rarity":"rare","id":"sidewinder","subtitle":"Snake","details":"A small desert rattlesnake of the American Southwest and Mexico that moves in looping sideways waves, leaving J-shaped tracks in loose sand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crotalus%20cerastes%20mesquite%20springs%20CA-2.jpg?width=1024"},{"name":"Eastern Massasauga","rarity":"rare","id":"eastern-massasauga","subtitle":"Snake","details":"A small, shy rattlesnake of Great Lakes and prairie wetlands, grey with dark blotches, sheltering in crayfish burrows and hibernating in fens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sistrurus%20catenatus%20Stanton%204.jpg?width=1024"},{"name":"Indian Cobra","rarity":"rare","id":"indian-cobra","subtitle":"Snake","details":"Famous across South Asia, this cobra spreads a wide hood marked, in many individuals, with a spectacled pattern on the back of the hood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/N.%20kaouthia%20hoodmark.jpg?width=1024"},{"name":"Monocled Cobra","rarity":"rare","id":"monocled-cobra","subtitle":"Snake","details":"A South and Southeast Asian cobra named for the single O-shaped eye mark on its hood, frequenting wetlands, rice fields and mangrove edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/N.kaouthia.jpg?width=1024"},{"name":"Egyptian Cobra","rarity":"rare","id":"egyptian-cobra","subtitle":"Snake","details":"A large cobra of North and East African savannas and arid country, ranging from yellowish to dark brown and long woven into the region's art.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/N.%20haje%20legionis.jpg?width=1024"},{"name":"Cape Cobra","rarity":"rare","id":"cape-cobra","subtitle":"Snake","details":"A slender, variable cobra of southern African shrubland, coloured yellow, golden or dark brown, and an agile climber as well as ground hunter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20cobra%20Naja%20nivea%20mature%20male%20hooding%20in%20defensive%20threat%20pose%20IMG%206734s.jpg?width=1024"},{"name":"Red-bellied Black Snake","rarity":"rare","id":"red-bellied-black-snake","subtitle":"Snake","details":"A glossy black snake of eastern Australian waterways with a striking crimson belly, often seen basking near creeks, dams and swamp edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pseudechis%20porphyriacus%2001.jpg?width=1024"},{"name":"Common Death Adder","rarity":"rare","id":"common-death-adder","subtitle":"Snake","details":"A short, thick Australian viper-like elapid that lies hidden in litter and wiggles its thin tail tip as a lure to draw prey within striking range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acanthophis%20antarcticus%20444996749.jpg?width=1024"},{"name":"Jararaca","rarity":"rare","id":"jararaca","subtitle":"Snake","details":"A slender, patterned pit viper of southern Brazil and neighbouring countries, common in forest edges, farms and gardens near ground cover.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bothrops%20jararaca-PE%20Serra%20do%20Mar-Jpdandretta%28001%29.jpg?width=1024"},{"name":"Blue Pit Viper","rarity":"rare","id":"blue-pit-viper","subtitle":"Snake","details":"An island form of the white-lipped pit viper found on Indonesia's Lesser Sunda Islands, coloured a startling turquoise blue in many populations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trimeresurus%20Insularis%2C%20si%20Cantik%20yang%20Mematikan.jpg?width=1024"},{"name":"Mangrove Pit Viper","rarity":"rare","id":"mangrove-pit-viper","subtitle":"Snake","details":"A stout purple-brown pit viper of Southeast Asian mangroves and coastal forests, spending the day coiled on low branches over tidal water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trimeresurus%20purpureomaculatus%20139165934.jpg?width=1024"},{"name":"Wagler's Pit Viper","rarity":"rare","id":"waglers-pit-viper","subtitle":"Snake","details":"A green, triangular-headed tree viper of Southeast Asian rainforest; females grow much larger and darker-patterned than the small green males.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tropidolaemus%20wagleri%2C%20Wagler%27s%20palm%20pit%20viper%20-%20Takua%20Pa%20District%2C%20Phang-nga%20Province%20%2848238132136%29.jpg?width=1024"},{"name":"Copperhead","rarity":"rare","id":"copperhead","subtitle":"Snake","details":"A chestnut pit viper of eastern North American woodland, its hourglass bands the colour of dead leaves making it nearly invisible on the forest floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agkistrodon%20contortrix%20-%20Nantes.jpg?width=1024"},{"name":"Horned Viper","rarity":"rare","id":"horned-viper","subtitle":"Snake","details":"A sidewinding desert viper of North Africa and Arabia with horn-like scales above its eyes, burying itself in sand with only its head showing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hornviper%20Cerastes%20cerastes.jpg?width=1024"},{"name":"European Adder","rarity":"rare","id":"european-adder","subtitle":"Snake","details":"Europe's widespread small viper, found from Britain to the Pacific, recognised by the dark zigzag down its back and its tolerance of cool climates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Benny%20Trapp%20Vipera%20berus.jpg?width=1024"},{"name":"Asp Viper","rarity":"rare","id":"asp-viper","subtitle":"Snake","details":"A stocky viper of southern Europe's rocky hills and sunny slopes, grey to brown with dark bars, and a slightly upturned tip to its snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vipera%20aspis%20aspis.jpg?width=1024"},{"name":"Central Bearded Dragon","rarity":"rare","id":"central-bearded-dragon","subtitle":"Lizard","details":"An Australian desert lizard named for the spiky throat pouch it puffs and darkens in display. It waves an arm to signal appeasement.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pogona%20vitticeps%20102336479.jpg?width=1024"},{"name":"Leopard Gecko","rarity":"rare","id":"leopard-gecko","subtitle":"Lizard","details":"A ground gecko of rocky deserts from Iran to India, named for its spotted coat. Unlike most geckos, it has movable eyelids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eublepharis%20macularius%20%283828139509%29.jpg?width=1024"},{"name":"Crested Gecko","rarity":"rare","id":"crested-gecko","subtitle":"Lizard","details":"A New Caledonian gecko with a fringe of spines over its eyes like eyelashes. It lacks eyelids and licks its eyeballs clean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gekon%20orz%C4%99siony%2C%20Correlophus%20ciliatus.jpg?width=1024"},{"name":"Madagascar Giant Day Gecko","rarity":"rare","id":"madagascar-giant-day-gecko","subtitle":"Lizard","details":"A large, emerald day gecko of Madagascar with red head markings. Active by day, it clings to palms and banana plants. It eats nectar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Madagascar%20giant%20day%20gecko%20%28Phelsuma%20grandis%29%20Nosy%20Komba.jpg?width=1024"},{"name":"Parson's Chameleon","rarity":"rare","id":"parsons-chameleon","subtitle":"Lizard","details":"One of the largest chameleons, from the rainforests of eastern Madagascar. Males carry a pair of small horns on the snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calumma%20parsonii%2028551455.jpg?width=1024"},{"name":"Perentie","rarity":"rare","id":"perentie","subtitle":"Lizard","details":"Australia's largest monitor, a fast and wary hunter of the arid interior. Its patterned hide blends with red rock and spinifex.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Perentie%20%28Varanus%20giganteus%29%20at%20Perth%20Zoo%2C%20February%202023%2001.jpg?width=1024"},{"name":"Lace Monitor","rarity":"rare","id":"lace-monitor","subtitle":"Lizard","details":"A large Australian tree-climbing monitor with cream bands and speckles. It raids nests and scavenges across eastern forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lace%20Monitor%2C%20Varanus%20Varius.jpg?width=1024"},{"name":"Black-throated Monitor","rarity":"rare","id":"black-throated-monitor","subtitle":"Lizard","details":"A heavy southern African monitor with a pale throat and banded tail. It digs up prey and climbs well despite its bulk. It is a savanna specialist.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rock%20monitor%2C%20Varanus%20albigularis%2C%20also%20called%20commonly%20the%20white-throated%20monitor%20or%20leguaan.%20%2848206380016%29.jpg?width=1024"},{"name":"Texas Horned Lizard","rarity":"rare","id":"texas-horned-lizard","subtitle":"Lizard","details":"A flat, horn-crowned lizard of Texas and Mexico that feeds almost entirely on harvester ants. It can squirt blood from its eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phrynosoma%20cornutum%20293505046.jpg?width=1024"},{"name":"Galapagos Land Iguana","rarity":"rare","id":"galapagos-land-iguana","subtitle":"Lizard","details":"A yellow-orange iguana of the Galapagos Islands that feeds on prickly pear cactus, pads, flowers and fallen fruit alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conolophus%20subcristatus%20%28North%20Seymour%204%29.jpg?width=1024"},{"name":"Desert Iguana","rarity":"rare","id":"desert-iguana","subtitle":"Lizard","details":"A pale, heat-loving iguana of the Sonoran and Mojave deserts. Active at midday temperatures that drive most lizards to shade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Desert%20iguana%20%28Dipsosaurus%20dorsalis%29%20%2820526299159%29.jpg?width=1024"},{"name":"Common Chuckwalla","rarity":"rare","id":"common-chuckwalla","subtitle":"Lizard","details":"A bulky rock-dwelling iguana of the American Southwest. Wedging into cracks, it inflates its lungs to lock itself in place.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sauromalus%20ater%20%283%29.jpg?width=1024"},{"name":"Emerald Tree Monitor","rarity":"rare","id":"emerald-tree-monitor","subtitle":"Lizard","details":"A slender, bright green monitor of New Guinea that lives in trees. Its long tail is prehensile and grips like a fifth limb.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanidae%20Varanus%20prasinus%201.jpg?width=1024"},{"name":"Crocodile Monitor","rarity":"rare","id":"crocodile-monitor","subtitle":"Lizard","details":"A very long, slender New Guinea monitor with an exceptionally long tail. It is an agile climber in lowland rainforest. It climbs well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanus%20Salvadorii%20K%C3%B6ln%20Zoo%2031122014%202.jpg?width=1024"},{"name":"Spiny-tailed Monitor","rarity":"rare","id":"spiny-tailed-monitor","subtitle":"Lizard","details":"A small Australian monitor with a spiny, curled tail, also called the ackie. It shelters in rock cracks and termite mounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanidae%20Varanus%20acanthurus%201.jpg?width=1024"},{"name":"Ornate Mastigure","rarity":"rare","id":"ornate-mastigure","subtitle":"Lizard","details":"A vividly coloured spiny-tailed lizard of Arabian and northeast African deserts, the males flushing blue in breeding season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PikiWiki%20Israel%2079915%20uromastyx%20ornata.jpg?width=1024"},{"name":"Shingleback Skink","rarity":"rare","id":"shingleback-skink","subtitle":"Lizard","details":"A stout Australian skink with a fat, pinecone-like tail that mirrors its head, confusing predators about which end is which.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bobtail%20%28Tiliqua%20rugosa%29%20on%20the%20Bickley%20Reservoir%20Walk%2C%20Korung%20National%20Park%2C%20November%202024%2001.jpg?width=1024"},{"name":"Green and Black Poison Dart Frog","rarity":"rare","id":"green-and-black-poison-dart-frog","subtitle":"Frog","details":"A glossy green and black dart frog of Central and northern South America, living on the rainforest floor near small streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dendrobates%20auratus%20-%20Goldbaumsteiger%20203695198.jpg?width=1024"},{"name":"Yellow-banded Poison Dart Frog","rarity":"rare","id":"yellow-banded-poison-dart-frog","subtitle":"Frog","details":"A bold yellow and black dart frog from Venezuela and nearby countries. Its bands vary, and it calls with a soft musical trill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bumblebee%20Poison%20Frog%20Dendrobates%20leucomelas.jpg?width=1024"},{"name":"Amazon Milk Frog","rarity":"rare","id":"amazon-milk-frog","subtitle":"Frog","details":"A large blue-grey tree frog of the Amazon canopy, with dark bands and golden eyes. It breeds in water-filled tree holes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2017-05-21%20AT%20Wien%2022%20Donaustadt%2C%20Palmenhaus%20Hirschstetten%2C%20Trachycephalus%20resinifictrix%20%2850935521603%29.jpg?width=1024"},{"name":"Vietnamese Mossy Frog","rarity":"rare","id":"vietnamese-mossy-frog","subtitle":"Frog","details":"A lumpy green and brown frog of northern Vietnam whose warty, mottled skin makes it look exactly like a clump of wet moss.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Theloderma%20corticale%20C%C3%BAc%20Ph%C6%B0%C6%A1ng%2006.jpg?width=1024"},{"name":"Malayan Horned Frog","rarity":"rare","id":"malayan-horned-frog","subtitle":"Frog","details":"A leaf-litter frog of Southeast Asia with pointed horns over its eyes and a pointed snout, perfectly shaped like a dead leaf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Megophryidae%20Megophrys%20nasuta%203.jpg?width=1024"},{"name":"Budgett's Frog","rarity":"rare","id":"budgetts-frog","subtitle":"Frog","details":"A broad, flat-headed frog of the South American Chaco. It spends the long dry season in a cocoon of shed skin underground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lepidobatrachus%20laevis-20260816200803.jpg?width=1024"},{"name":"Lake Titicaca Frog","rarity":"rare","id":"lake-titicaca-frog","subtitle":"Frog","details":"A large, fully aquatic frog of high Lake Titicaca, with loose folds of skin that help it absorb oxygen from the cold water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Telmatobius%20culeus%20VA.jpg?width=1024"},{"name":"Darwin's Frog","rarity":"rare","id":"darwins-frog","subtitle":"Frog","details":"A tiny leaf-shaped frog of Chile and Argentina. Males carry developing tadpoles inside their vocal sacs until they hop out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhinoderma%20darwinii.jpg?width=1024"},{"name":"Southern Corroboree Frog","rarity":"rare","id":"southern-corroboree-frog","subtitle":"Frog","details":"A small black frog with brilliant yellow stripes, from Australia's alpine bogs and swamps. It walks more often than it hops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Corroboree%20Frog%20at%20Taronga%20Zoo%20in%20Sydney.jpg?width=1024"},{"name":"Clown Tree Frog","rarity":"rare","id":"clown-tree-frog","subtitle":"Frog","details":"A small Amazon tree frog that changes from yellow-brown by day to dark with pale webbing patterns at night, like a clown suit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dendropsophus%20ebraccatus01.jpg?width=1024"},{"name":"Indian Bullfrog","rarity":"rare","id":"indian-bullfrog","subtitle":"Frog","details":"A large greenish frog of South Asia, common in flooded fields in monsoon season. Breeding males turn bright yellow with blue sacs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bull%20frog%20Hoplobatrachus%20tigerinus%20IMG%200517.jpg?width=1024"},{"name":"Oriental Fire-bellied Toad","rarity":"rare","id":"oriental-fire-bellied-toad","subtitle":"Toad","details":"A small toad of Korea, China and nearby Russia, green and black above and brilliant red-orange below as a warning display.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bombina%20Orientalis%20%22Circuit%22.jpg?width=1024"},{"name":"Variable Harlequin Frog","rarity":"rare","id":"variable-harlequin-frog","subtitle":"Toad","details":"A slender, brightly patterned frog of Costa Rica and Panama streams, coloured in gold, orange, red or green with dark marks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2022-01-28%20Atelopus%20varius%20lowland%20x%20lowland.jpg?width=1024"},{"name":"Kihansi Spray Toad","rarity":"rare","id":"kihansi-spray-toad","subtitle":"Toad","details":"A tiny yellowish toad from one Tanzanian gorge, living in the constant spray of waterfalls. Females give birth to tiny toadlets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kihansi%20Spray%20Toad4.jpg?width=1024"},{"name":"White-lipped Tree Frog","rarity":"rare","id":"white-lipped-tree-frog","subtitle":"Frog","details":"One of the world's largest tree frogs, from New Guinea and northern Australia, named for the crisp white stripe on its lower jaw.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Litoria%20infrafrenata1.jpg?width=1024"},{"name":"Golden Mantella","rarity":"rare","id":"golden-mantella","subtitle":"Frog","details":"A tiny, uniform golden-orange frog from a few Madagascar wetlands. It is active by day on the forest floor among leaf litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mantella%20aurantiaca%2C%20Peyrieras%2002.JPG?width=1024"},{"name":"Diamondback Terrapin","rarity":"rare","id":"diamondback-terrapin","subtitle":"Terrapin","details":"Brackish marsh terrapin of the Atlantic and Gulf coasts of the United States, with a grey patterned shell and speckled skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malaclemys%20terrapin%20%28diamondback%20terrapin%29%202%20%2815101239604%29.jpg?width=1024"},{"name":"Wood Turtle","rarity":"rare","id":"wood-turtle","subtitle":"Turtle","details":"North American stream turtle with a sculpted, pyramid-like shell, orange neck markings and a diet ranging from worms to berries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wood%20turtle%20%28Glyptemys%20insculpta%29%2C%20Coventry%2C%20RI%20%2832047582581%29.jpg?width=1024"},{"name":"Blanding's Turtle","rarity":"rare","id":"blandings-turtle","subtitle":"Turtle","details":"North American marsh turtle with a bright yellow chin and throat, a domed speckled shell and a gently hinged lower shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blandings%20turtle%20on%20ground%20in%20wild%20emydoidea%20blandingii.jpg?width=1024"},{"name":"Hermann's Tortoise","rarity":"rare","id":"hermanns-tortoise","subtitle":"Tortoise","details":"Mediterranean tortoise of southern Europe, with a yellow and black patterned shell and a single horny spur behind each thigh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Testudo%20hermanni%20on%20Thasos.JPG?width=1024"},{"name":"Greek Tortoise","rarity":"rare","id":"greek-tortoise","subtitle":"Tortoise","details":"Widespread tortoise around the Mediterranean, named for the Greek-key pattern on its shell, with a large spur on each thigh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tunisian%20tortoise%20%28Testudo%20graeca%20nabeulensis%29%20male%20Cap%20Bon%202.jpg?width=1024"},{"name":"Pancake Tortoise","rarity":"rare","id":"pancake-tortoise","subtitle":"Tortoise","details":"Flat-shelled East African tortoise that squeezes into rock crevices for shelter, its thin flexible shell unlike other tortoises.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pancake%20tortoise%20%28Malacochersus%20tornieri%29%20at%20Nairobi%20Snake%20Park.jpg?width=1024"},{"name":"Spiny Softshell Turtle","rarity":"rare","id":"spiny-softshell-turtle","subtitle":"Turtle","details":"North American river softshell with a leathery, spiny-edged flat shell, long snorkel snout and strongly webbed, clawed feet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dornrand-Weichschildkr%C3%B6te%20%28Apalone%20spinifera%29%2C%20Seitenansicht.jpg?width=1024"},{"name":"Reeves's Turtle","rarity":"rare","id":"reevess-turtle","subtitle":"Turtle","details":"Small pond turtle of China, Korea and Japan, with three clear keels along its brown shell and pale stripes along its neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mauremys%20reevesii%20356786109.jpg?width=1024"},{"name":"Desert Tortoise","rarity":"rare","id":"desert-tortoise","subtitle":"Tortoise","details":"Tortoise of the Mojave and Sonoran deserts, sheltering in burrows from heat, with a domed brown shell and stout elephant-like legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Desert%20Tortoise%20%28Gopherus%20agassizii%29%20%28c698c0ab-155d-451f-6767-3d6803c9e569%29.jpg?width=1024"},{"name":"Marginated Tortoise","rarity":"rare","id":"marginated-tortoise","subtitle":"Tortoise","details":"Largest European tortoise, from southern Greece, recognised by the flared, skirt-like rear edge of its elongated dark shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Klokschildpad%20-%20Marginated%20Tortoise%20-%20Testudo%20marginata.jpg?width=1024"},{"name":"American Crocodile","rarity":"rare","id":"american-crocodile","subtitle":"Crocodile","details":"A coastal crocodile of the Americas, from Florida to northern South America, growing to about 5 metres, with a long, tapering snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20Crocodile%2C%20Costa%20Rica.jpg?width=1024"},{"name":"Orinoco Crocodile","rarity":"rare","id":"orinoco-crocodile","subtitle":"Crocodile","details":"A large crocodile of the Orinoco River basin in Venezuela and Colombia, reaching about 5 metres, with a long, relatively slender snout.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orinoco%20Crocodile%20%28Crocodylus%20intermedius%29%20%2834566274184%29.jpg?width=1024"},{"name":"Mugger Crocodile","rarity":"rare","id":"mugger-crocodile","subtitle":"Crocodile","details":"A broad-snouted crocodile of rivers, lakes and marshes from Iran across India to Sri Lanka, reaching about 4 to 5 metres in length.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mugger%20crocodile%20%28Crocodylus%20palustris%29.jpg?width=1024"},{"name":"False Gharial","rarity":"rare","id":"false-gharial","subtitle":"Gharial","details":"A slender-snouted crocodilian of peat swamps and slow rivers in Malaysia and Indonesia, reaching about 5 metres, feeding mostly on fish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tomistoma%20schlegelii%20%282%29.jpg?width=1024"},{"name":"Tiger Salamander","rarity":"rare","id":"tiger-salamander","subtitle":"Salamander","details":"A stout, yellow-barred mole salamander widespread across North America, it breeds in fish-free ponds and shelters underground by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tiger%20Salamander%20%28Ambystoma%20tigrinum%29.jpg?width=1024"},{"name":"California Tiger Salamander","rarity":"rare","id":"california-tiger-salamander","subtitle":"Salamander","details":"A black-and-cream mole salamander of California grasslands, it spends most of the year in burrows and breeds in seasonal pools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/California%20Tiger%20Salamander.jpg?width=1024"},{"name":"Mudpuppy","rarity":"rare","id":"mudpuppy","subtitle":"Salamander","details":"A permanently aquatic salamander of North American lakes and rivers, it keeps bushy red external gills and stays active all winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Mudpuppy%20%28Necturus%20maculosus%29%20-%20Flickr%20-%202ndPeter.jpg?width=1024"},{"name":"Greater Siren","rarity":"rare","id":"greater-siren","subtitle":"Salamander","details":"An eel-like, fully aquatic salamander of southeastern wetlands, it has external gills, tiny front legs and no hind legs at all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siren%20lacertina%2057138478.jpg?width=1024"},{"name":"Great Crested Newt","rarity":"rare","id":"great-crested-newt","subtitle":"Newt","details":"A large European newt whose breeding males grow a tall, jagged crest and a bright orange belly patterned with dark blotches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kammmolchmaennchen.jpg?width=1024"},{"name":"California Giant Salamander","rarity":"rare","id":"california-giant-salamander","subtitle":"Salamander","details":"A large, marbled salamander of cool redwood-forest streams in coastal California and Oregon, with a broad head and strong jaws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dicamptodon%20ensatus%20terrestrial%20adult.jpg?width=1024"},{"name":"African Rock Python","rarity":"uncommon","id":"african-rock-python","subtitle":"Snake","details":"Africa's largest snake, a powerful python of savannas and forest edges near water, with wild females recorded at around 5 metres or more.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adult%20Female%20Python%20sebae.jpg?width=1024"},{"name":"Indian Python","rarity":"uncommon","id":"indian-python","subtitle":"Snake","details":"A large, heavy python of South Asian forests and wetlands, pale with dark blotches, often found near water and in mammal burrows and caves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indian%20python%20%40%20Kanjirappally%2004.jpg?width=1024"},{"name":"Ball Python","rarity":"uncommon","id":"ball-python","subtitle":"Snake","details":"A small West African python named for curling into a tight ball when nervous; in the wild it rests in grassland burrows and hunts at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pythonidae%20Python%20regius%203.jpg?width=1024"},{"name":"Carpet Python","rarity":"uncommon","id":"carpet-python","subtitle":"Snake","details":"A variable Australian python found in forests, suburbs and farms across the mainland, its patterned carpet of blotches varying by region.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morelia%20spilota%20variegata%202.jpg?width=1024"},{"name":"Green Tree Python","rarity":"uncommon","id":"green-tree-python","subtitle":"Snake","details":"A bright green tree python of New Guinea and Cape York rainforest, resting in a neat coil on branches with its head folded in the centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morelia%20viridis%209.jpg?width=1024"},{"name":"Woma Python","rarity":"uncommon","id":"woma-python","subtitle":"Snake","details":"A narrow-headed Australian desert python with orange-brown bands, hunting in burrows where it pins prey against the tunnel walls to subdue it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Woma%20python%20%28Aspidites%20ramsayi%29%20at%20Perth%20Zoo%2C%20February%202023%2001.jpg?width=1024"},{"name":"Black-headed Python","rarity":"uncommon","id":"black-headed-python","subtitle":"Snake","details":"An unmistakable Australian python with a glossy jet-black head and neck, found in arid country and termite mounds across the northern half.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black-headed%20python%20%28Aspidites%20melanocephalus%29%20at%20Perth%20Zoo%2C%20February%202023%2001.jpg?width=1024"},{"name":"Olive Python","rarity":"uncommon","id":"olive-python","subtitle":"Snake","details":"One of Australia's largest snakes, this smooth-scaled olive-brown python lives near rocky waterholes and gorges in the tropical north.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Liasis%20olivaceus%20188042979.jpg?width=1024"},{"name":"Blood Python","rarity":"uncommon","id":"blood-python","subtitle":"Snake","details":"A short, thick python of Southeast Asian swamps and marshes, richly coloured in reds and oranges and spending much time half-buried in mud.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Python%20brongersmai%2C%20Brongersma%27s%20short-tailed%20python.jpg?width=1024"},{"name":"Rubber Boa","rarity":"uncommon","id":"rubber-boa","subtitle":"Snake","details":"A smooth, blunt-tailed boa of western North America whose loose, rubbery skin and uniform brown colour make both ends look much alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charina%20bottae%20129248375.jpg?width=1024"},{"name":"Rosy Boa","rarity":"uncommon","id":"rosy-boa","subtitle":"Snake","details":"A gentle, slow boa of the American Southwest and Baja California, striped in cream and rose-brown, sheltering in rocky desert canyons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rosy%20boa%20%28Lichanura%20trivirgata%29.jpg?width=1024"},{"name":"Kenyan Sand Boa","rarity":"uncommon","id":"kenyan-sand-boa","subtitle":"Snake","details":"A stout East African sand boa that spends the day buried in loose soil, its orange and brown blotches hidden until it ambushes prey at dusk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eryx%20colubrinus%20close%20up.jpg?width=1024"},{"name":"Eastern Indigo Snake","rarity":"uncommon","id":"eastern-indigo-snake","subtitle":"Snake","details":"North America's longest native snake, a glossy blue-black species of Florida and Georgia longleaf pine woods, sharing burrows with tortoises.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/EasternIndigo2010.jpg?width=1024"},{"name":"Coachwhip","rarity":"uncommon","id":"coachwhip","subtitle":"Snake","details":"A long, whip-thin and very fast snake of open American and Mexican country, its scales patterned like braided leather along a slender body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Masticophis%20flagellum%20287726810.jpg?width=1024"},{"name":"King Rat Snake","rarity":"uncommon","id":"king-rat-snake","subtitle":"Snake","details":"A large, bold Asian rat snake of forests and farmland, yellow-green to dark with pale scale edges, known for its musky defensive odour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elaphe%20carinata%20in%20Soochow%20University%2020070428.jpg?width=1024"},{"name":"Japanese Rat Snake","rarity":"uncommon","id":"japanese-rat-snake","subtitle":"Snake","details":"A large olive-green rat snake found across Japan's main islands, an excellent climber that hunts birds and mammals in trees and barns alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elaphe%20climacophora%20181953866.jpg?width=1024"},{"name":"Radiated Rat Snake","rarity":"uncommon","id":"radiated-rat-snake","subtitle":"Snake","details":"A fast, coppery-brown Asian rat snake with faint stripes, often found near water and villages, flattening its neck when it feels threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coelognathus%20radiatus.jpg?width=1024"},{"name":"Tiger Keelback","rarity":"uncommon","id":"tiger-keelback","subtitle":"Snake","details":"An East Asian keelback with bold black and red markings behind the head, unusual in storing toxins from the toads it eats in its neck glands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhabdophis%20tigrinus%20s5.jpg?width=1024"},{"name":"Checkered Keelback","rarity":"uncommon","id":"checkered-keelback","subtitle":"Snake","details":"A common waterside snake of South and Southeast Asia, olive with a chequered pattern, often seen hunting frogs around ponds and rice fields.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fowlea%20piscator%20102572879.jpg?width=1024"},{"name":"Eastern Hog-nosed Snake","rarity":"uncommon","id":"eastern-hog-nosed-snake","subtitle":"Snake","details":"A stout eastern North American snake famous for its dramatic bluff: hissing, flattening its neck, then rolling over and playing dead if pressed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20Hog-nosed%20Snake%20-%20Heterodon%20platirhinos%2C%20Meadowood%20Farm%20SRMA%2C%20Mason%20Neck%2C%20Virginia%20-%2001.jpg?width=1024"},{"name":"Western Hog-nosed Snake","rarity":"uncommon","id":"western-hog-nosed-snake","subtitle":"Snake","details":"A dusty plains snake with an upturned snout for digging in sandy soil, feeding heavily on toads across the Great Plains and northern Mexico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dipsadidae%20Heterodon%20nasicus%201.jpg?width=1024"},{"name":"Mussurana","rarity":"uncommon","id":"mussurana","subtitle":"Snake","details":"A dark, smooth-scaled South American snake that specialises in hunting other snakes, including pit vipers, in forest and savanna at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clelia%20clelia%20Pocone%20fzd%20santa%20ines%20MT%20OAVM2.jpg?width=1024"},{"name":"False Water Cobra","rarity":"uncommon","id":"false-water-cobra","subtitle":"Snake","details":"A large, fast South American swamp snake that flattens its neck into a cobra-like hood when alarmed, though it has no true hood or fixed fangs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hydrodynastes%20gigas%20Instituto%20Butant%C3%A3.jpg?width=1024"},{"name":"Oriental Whip Snake","rarity":"uncommon","id":"oriental-whip-snake","subtitle":"Snake","details":"A pencil-thin, bright green tree snake of Asian forests with a long pointed head, horizontal pupils and a forked tongue it flicks constantly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ahaetulla%20prasina%2C%20oriental%20whipsnake%20-%20Kaeng%20Krachan%20National%20Park.jpg?width=1024"},{"name":"Madagascar Ground Boa","rarity":"uncommon","id":"madagascar-ground-boa","subtitle":"Snake","details":"Madagascar's largest snake, a heavy reddish-brown ground boa of western forests that hunts lemurs, birds and rodents on the forest floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Madagascar%20ground%20boa%2C%20Acrantophis%20madagascariensis.jpg?width=800"},{"name":"Dumeril's Boa","rarity":"uncommon","id":"dumerils-boa","subtitle":"Snake","details":"A beautifully patterned ground boa of Madagascar's dry southwest, its grey-brown camouflage vanishing among leaf litter and dry scrub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dumeril%27s%20Madagascar%20ground%20boa%20%28Acrantophis%20dumerili%29%20male%20Reniala.jpg?width=1024"},{"name":"Amazon Tree Boa","rarity":"uncommon","id":"amazon-tree-boa","subtitle":"Snake","details":"A variable tree boa of Amazon forests, coloured from grey to orange, resting in a saddle coil over branches and hunting sleeping birds at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Corallus%20hortulanus%20in%20Ecuador.jpg?width=1024"},{"name":"Cuban Boa","rarity":"uncommon","id":"cuban-boa","subtitle":"Snake","details":"The Caribbean's largest snake, this Cuban endemic boa hunts in caves, forests and rocky country, sometimes gathering at cave mouths at dusk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chilabothrus%20angulifer%20in%20Ouwehands%20Dierenpark.jpg?width=1024"},{"name":"Yellow Anaconda","rarity":"uncommon","id":"yellow-anaconda","subtitle":"Snake","details":"A smaller relative of the green anaconda, this yellow-patterned boa lives in the Pantanal and other marshes of southern South America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eunectes%20notaeus%20111598447.jpg?width=1024"},{"name":"Green Anole","rarity":"uncommon","id":"green-anole","subtitle":"Lizard","details":"A small, colour-changing lizard of the southeastern US. Males flash a pink throat fan, called a dewlap, to claim territory.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anolis%20carolinensis-032.jpg?width=1024"},{"name":"Brown Anole","rarity":"uncommon","id":"brown-anole","subtitle":"Lizard","details":"A Cuban anole now widespread in Florida and the Gulf Coast. Males display with an orange-red dewlap and rapid push-up bouts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anolis%20sagrei%20108645763.jpg?width=1024"},{"name":"Knight Anole","rarity":"uncommon","id":"knight-anole","subtitle":"Lizard","details":"The largest anole, from Cuba, reaching over 30 centimetres. It is bright green with a pale stripe and a pinkish-white dewlap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anolis%20equestris%20152442105.jpg?width=1024"},{"name":"Common Five-lined Skink","rarity":"uncommon","id":"common-five-lined-skink","subtitle":"Lizard","details":"A glossy North American skink whose juveniles are black with five pale stripes and a brilliant blue tail that fades with age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plestiodon%20fasciatus%20219823091.jpg?width=1024"},{"name":"Broad-headed Skink","rarity":"uncommon","id":"broad-headed-skink","subtitle":"Lizard","details":"The largest skink of the southeastern US. Breeding males develop a swollen, orange-red head and defend tree territories.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Broad-headed%20Skink%20-%20Plestiodon%20laticeps%2C%20Sugarloaf%20Mountain%2C%20Dickerson%2C%20Maryland.jpg?width=1024"},{"name":"Cunningham's Skink","rarity":"uncommon","id":"cunninghams-skink","subtitle":"Lizard","details":"A spiny Australian skink that lives in family groups among rock crevices. It wedges itself in cracks using its keeled scales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Egernia%20cunninghami%20%2823945975808%29.jpg?width=1024"},{"name":"Common House Gecko","rarity":"uncommon","id":"common-house-gecko","subtitle":"Lizard","details":"A small Asian gecko that hunts insects around lights on walls at night. Its soft chirping calls are a familiar household sound.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hemidactylus%20frenatus%20mating%2C%20ventral%20view.jpg?width=1024"},{"name":"Mediterranean House Gecko","rarity":"uncommon","id":"mediterranean-house-gecko","subtitle":"Lizard","details":"A warty, pale gecko from the Mediterranean, now common on walls across warm regions worldwide. It is almost entirely nocturnal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hemidactylus%20Turcicus%20with%20Prey.jpg?width=1024"},{"name":"Moorish Wall Gecko","rarity":"uncommon","id":"moorish-wall-gecko","subtitle":"Lizard","details":"A robust gecko of the Mediterranean coast with spiny tubercles and a flattened head. It hunts moths around lamps after dark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/25-08-2017%20Moorish%20Geko%2C%20%28Tarentola%20mauritanica%29%2C%20Albufeira%20%281%29.JPG?width=1024"},{"name":"Western Fence Lizard","rarity":"uncommon","id":"western-fence-lizard","subtitle":"Lizard","details":"A spiny western US lizard famous for doing push-ups on fences and rocks. Males flash bright blue patches on belly and throat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sceloporus%20occidentalis%2C%20Sacramento%20County%2C%20California.jpg?width=1024"},{"name":"Eastern Fence Lizard","rarity":"uncommon","id":"eastern-fence-lizard","subtitle":"Lizard","details":"A rough-scaled lizard of pine forests and fence lines in the eastern US. It basks on logs and flees up the far side of trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20Fence%20Lizard%20-%20Sceloporus%20undulatus%2C%20Meadowood%20Farm%20SRMA%2C%20Mason%20Neck%2C%20Virginia%20%2840486057172%29.jpg?width=1024"},{"name":"Common Collared Lizard","rarity":"uncommon","id":"common-collared-lizard","subtitle":"Lizard","details":"A fast, colourful lizard of rocky US plains and Southwest, marked by two black collar bands. It can run on its hind legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crotaphytus%20collaris%20105559053.jpg?width=1024"},{"name":"Greater Earless Lizard","rarity":"uncommon","id":"greater-earless-lizard","subtitle":"Lizard","details":"A sand-coloured lizard of Texas and Mexican deserts with no external ear openings. Dark bars show under its lifted tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cophosaurus%20texanus%20%282007%29.jpg?width=1024"},{"name":"Zebra-tailed Lizard","rarity":"uncommon","id":"zebra-tailed-lizard","subtitle":"Lizard","details":"A desert lizard of the American Southwest with black-and-white banding under its tail, waved like a flag when a predator nears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pinkish%20Zebra-tailed%20lizard%20%28Callisaurus%20draconoides%29.jpg?width=1024"},{"name":"Common Side-blotched Lizard","rarity":"uncommon","id":"common-side-blotched-lizard","subtitle":"Lizard","details":"A tiny western US lizard named for the dark blotch behind its forelimb. Males come in orange, blue and yellow throat morphs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Desert%20Side-blotched%20Lizard%20-%20Uta%20stansburiana%20stejnegeri%2C%20White%20Sands%20National%20Monument%2C%20Alamogordo%2C%20New%20Mexico.jpg?width=1024"},{"name":"Ornate Tree Lizard","rarity":"uncommon","id":"ornate-tree-lizard","subtitle":"Lizard","details":"A small, intricately patterned lizard of the Southwest that climbs trees and rocks. Males show turquoise belly patches. It basks daily.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Urosaurus%20ornatus%20-%20Flickr%20-%20aspidoscelis%20%2812%29.jpg?width=1024"},{"name":"Long-nosed Leopard Lizard","rarity":"uncommon","id":"long-nosed-leopard-lizard","subtitle":"Lizard","details":"A long-snouted predator of western US deserts that hunts other lizards, including its own kind, plus insects and small snakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gambelia%20wislizenii%20105025074.jpg?width=1024"},{"name":"Flat-tailed Horned Lizard","rarity":"uncommon","id":"flat-tailed-horned-lizard","subtitle":"Lizard","details":"A flattened desert lizard of the Southwest with a single row of fringe scales and a dark stripe running down its spine. It eats ants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phrynosoma%20mcallii%201526390.jpg?width=1024"},{"name":"Pygmy Short-horned Lizard","rarity":"uncommon","id":"pygmy-short-horned-lizard","subtitle":"Lizard","details":"A tiny, round horned lizard of northwestern North America. It gives birth to live young, unusual among horned lizards. It eats ants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phrynosoma%20douglasii%2041603876%20%28rotate%29.jpg?width=1024"},{"name":"Australian Water Dragon","rarity":"uncommon","id":"australian-water-dragon","subtitle":"Lizard","details":"A semi-aquatic Australian lizard with a crest of spines and a banded tail. It dives into creeks and can stay under for 30 minutes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Australian%20Water%20Dragon%20Intellagama%20lesueurii%20Downfall%20Creek%207th%20Brigade%20Park%20Chermside%20P1080061.jpg?width=1024"},{"name":"Boyd's Forest Dragon","rarity":"uncommon","id":"boyds-forest-dragon","subtitle":"Lizard","details":"A crested rainforest lizard of Queensland that sits motionless on saplings, relying on camouflage rather than flight. It stays cryptic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boyd%27s%20forest%20dragon%20%28Lophosaurus%20boydii%29.jpg?width=1024"},{"name":"Jacky Dragon","rarity":"uncommon","id":"jacky-dragon","subtitle":"Lizard","details":"A small Australian dragon with a yellow mouth lining, flashed when threatened. It waves its tail to signal other jacky dragons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amphibolurus%20muricatus%20%2812210819943%29.jpg?width=1024"},{"name":"Sand Goanna","rarity":"uncommon","id":"sand-goanna","subtitle":"Lizard","details":"A widespread Australian monitor, also called Gould's goanna. It digs burrows and stands on its hind legs to survey the ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanus%20gouldii%2018082009a.jpg?width=1024"},{"name":"Yellow-spotted Monitor","rarity":"uncommon","id":"yellow-spotted-monitor","subtitle":"Lizard","details":"A large northern Australian monitor that digs deep burrows in floodplains and is a powerful swimmer in the wet season. It digs well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanus%20panoptes%20%2815848624016%29%202.jpg?width=1024"},{"name":"Mangrove Monitor","rarity":"uncommon","id":"mangrove-monitor","subtitle":"Lizard","details":"A Pacific and Southeast Asian monitor of mangroves and coasts. It swims between islands and feeds on crabs and fish. It swims well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanus%20indicus%20MNHN.jpg?width=1024"},{"name":"Timor Monitor","rarity":"uncommon","id":"timor-monitor","subtitle":"Lizard","details":"A small, spotted monitor of Timor and nearby islands. A nimble climber, it shelters in hollow trees and rock piles. It climbs well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blumeng%C3%A4rten%20Hirschstetten%202016-02-21%20Timor-Waran%20%28Varanus%20timorensis%29%20a.jpg?width=1024"},{"name":"European Green Lizard","rarity":"uncommon","id":"european-green-lizard","subtitle":"Lizard","details":"A large, vivid green lizard of southern and central Europe. Breeding males develop a bright blue throat and head sides. It feeds on insects and fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lacerta%20viridis%20-%20couple%2001.JPG?width=1024"}]});
